(3122, 1, 1, 'resources', 'resources', NULL, NULL, 99, 'ресурсы, средства, запасы', '', 'A process is an instance of a program that has its own {resources} and virtual address space.', NULL, 1, '2025-08-29 23:14:24', '2026-01-18 09:59:21', 100, 100, 0.4200867381133947),
(3123, 1, 1, 'ensuring', 'ensuring', NULL, NULL, 5, 'обеспечение, гарантирование; обеспечивать, гарантировать', '', 'This isolates processes from each other, {ensuring} that one process cannot affect the data of another.', NULL, 1, '2025-08-29 23:14:41', '2026-04-22 18:09:17', 96, 94, 0.6393995821842919),
(3124, 1, 1, 'unit', 'unit', NULL, NULL, 99, 'единица, блок, модуль', '', 'A thread is a {unit} of execution that uses the resources of its process.', NULL, 1, '2025-08-29 23:14:48', '2026-04-24 09:35:15', 100, 100, 0.40953805056357573),
(3125, 1, 1, 'uses', 'uses', NULL, NULL, 99, 'использования, применения; использовать, применять', '', 'A thread is a unit of execution that {uses} the resources of its process.', NULL, 1, '2025-08-29 23:15:03', '2026-01-18 10:09:59', 100, 100, 0.5868323041003498),
(3126, 1, 1, 'exchange', 'exchange', NULL, NULL, 99, 'обмен, передача, обменивание; обменивать, обмениваться', '', 'Data {exchange} between threads within the same process is faster than between separate processes.', NULL, 1, '2025-08-29 23:15:14', '2026-01-18 10:10:57', 100, 100, 0.6711865194804841),
(3127, 1, 1, 'faster', 'faster', NULL, NULL, 99, 'быстрее, ускоренный', '', 'Data exchange between threads within the same process is {faster} than between separate processes.', NULL, 1, '2025-08-29 23:15:52', '2026-01-18 10:01:25', 100, 100, 0.7338459768647756),
(3128, 1, 1, 'separate', 'separate', NULL, NULL, 99, 'отдельный, раздельный, самостоятельный; разделять, отделять', '', 'Data exchange between threads within the same process is faster than between {separate} processes.', NULL, 1, '2025-08-29 23:16:19', '2026-01-18 17:07:33', 100, 100, 0.5254267198270436),
(3129, 1, 1, 'entire', 'entire', NULL, NULL, 99, 'целый, полный, весь', '', 'If a thread enters an infinite loop, only that thread is blocked, not the {entire} system.', NULL, 1, '2025-08-29 23:16:31', '2026-01-18 08:59:23', 100, 100, 0.6231421582616327),
(3130, 1, 1, 'system', 'system', NULL, NULL, 99, 'система, устройство, строй', '', 'If a thread enters an infinite loop, only that thread is blocked, not the entire {system}.', NULL, 1, '2025-08-29 23:16:49', '2026-01-18 08:51:04', 100, 100, 0.07041892322750662),
(3131, 1, 1, 'switching', 'switching', NULL, NULL, 99, 'переключение, смена; переключать, менять', '', 'Context {switching} is the mechanism that lets the system share CPU time among threads.', NULL, 1, '2025-08-29 23:17:12', '2026-04-24 09:33:32', 100, 100, 0.33379649215731444),
(3132, 1, 1, 'lets', 'lets', NULL, NULL, 99, 'позволять, давать возможность', '', 'Context switching is the mechanism that {lets} the system share CPU time among threads.', NULL, 1, '2025-08-29 23:17:47', '2026-01-18 17:06:31', 100, 100, 0.7087734487920753),
(3133, 1, 1, 'share', 'share', NULL, NULL, 5, 'доля, часть; делить, распределять', '', 'Context switching is the mechanism that lets the system {share} CPU time among threads.', NULL, 1, '2025-08-29 23:18:36', '2026-02-14 10:04:04', 2, 1, 0.0025829272368763827),
(3134, 1, 1, 'CPU', 'cpu', NULL, NULL, 99, 'ЦП, процессор', '', 'Context switching is the mechanism that lets the system share {CPU} time among threads.', NULL, 1, '2025-08-29 23:18:46', '2025-09-03 13:05:45', 100, 100, 0.27050042736390645),
(3135, 1, 1, 'among', 'among', NULL, NULL, 99, 'среди, между', '', 'Context switching is the mechanism that lets the system share CPU time {among} threads.', NULL, 1, '2025-08-29 23:19:08', '2026-04-24 09:28:41', 100, 100, 0.5584509610742805),
(3136, 1, 1, 'improves', 'improves', NULL, NULL, 99, 'улучшать, повышать', '', 'It {improves} responsiveness and reliability, but may reduce performance due to switching overhead.', NULL, 1, '2025-08-29 23:19:24', '2026-04-22 19:52:49', 100, 100, 0.9773986292792471),
(3137, 1, 1, 'responsiveness', 'responsiveness', NULL, NULL, 5, 'отзывчивость, отклик', '', 'It improves {responsiveness} and reliability, but may reduce performance due to switching overhead.', NULL, 1, '2025-08-29 23:19:37', '2026-02-15 12:49:52', 3, 2, 0.09471592036515095),
(3138, 1, 1, 'reliability', 'reliability', NULL, NULL, 5, 'надёжность', '', 'It improves responsiveness and {reliability}, but may reduce performance due to switching overhead.', NULL, 1, '2025-08-29 23:19:46', '2026-02-15 10:07:33', 3, 2, 0.4658308508487706),
(3139, 1, 1, 'may', 'may', NULL, NULL, 99, 'может', '', 'It improves responsiveness and reliability, but {may} reduce performance due to switching overhead.', NULL, 1, '2025-08-29 23:19:57', '2026-01-18 10:04:43', 100, 100, 0.4563094847428701),
(3140, 1, 1, 'reduce', 'reduce', NULL, NULL, 99, 'снижать, уменьшать', '', 'It improves responsiveness and reliability, but may {reduce} performance due to switching overhead.', NULL, 1, '2025-08-29 23:20:16', '2026-04-24 08:44:46', 100, 100, 0.6729842635551321),
(3141, 1, 1, 'overhead', 'overhead', NULL, NULL, 5, 'накладные расходы, издержки', '', 'It improves responsiveness and reliability, but may reduce performance due to switching {overhead}.', NULL, 1, '2025-08-29 23:20:37', '2026-04-22 17:38:46', 96, 94, 0.045006523882044965),
(3142, 1, 1, 'due to', 'due to', NULL, NULL, 99, 'из-за, вследствие, по причине', '', '', NULL, 2, '2025-08-29 23:20:50', '2026-01-18 10:03:24', 100, 100, 0.7307553149114878),
(3143, 1, 1, 'active', 'active', NULL, NULL, 99, 'активный, действенный, рабочий', '', '- Foreground thread is an {active} thread;', NULL, 1, '2025-08-29 23:21:11', '2026-01-18 08:59:56', 100, 100, 0.7363171789202068),
(3144, 1, 1, 'forcibly', 'forcibly', NULL, NULL, 5, 'принудительно, насильно', '', 'when all foreground threads finish, all running background threads are also {forcibly} terminated, and the application exits.', NULL, 1, '2025-08-29 23:21:25', '2026-02-15 12:47:08', 3, 2, 0.8275400975975581),
(3145, 1, 1, 'terminated', 'terminated', NULL, NULL, 5, 'завершённый, прерванный; завершать, прекращать', '', 'when all foreground threads finish, all running background threads are also forcibly {terminated}, and the application exits.', NULL, 1, '2025-08-29 23:21:42', '2026-02-27 10:50:25', 20, 19, 0.0026809470753008007),
(3146, 1, 1, 'exits', 'exits', NULL, NULL, 5, 'выходы, выход; выходить, завершать работу', '', 'when all foreground threads finish, all running background threads are also forcibly terminated, and the application {exits}.', NULL, 1, '2025-08-29 23:22:02', '2026-02-24 13:33:40', 16, 15, 0.5307844733174746),
(3147, 1, 1, 'switched', 'switched', NULL, NULL, 5, 'переключённый, изменённый; переключать, поменять', '', 'A thread can be {switched} between foreground and background, and you can check whether a thread is background or foreground using the `IsBackground` property.', NULL, 1, '2025-08-29 23:22:26', '2026-02-14 09:50:50', 2, 1, 0.6458795560951154),
(3148, 1, 1, 'IsBackground', 'isbackground', NULL, NULL, 5, 'IsBackground, свойство', '', 'A thread can be switched between foreground and background, and you can check whether a thread is background or foreground using the `{IsBackground}` property.', NULL, 1, '2025-08-29 23:22:38', '2026-02-14 10:04:09', 2, 1, 0.6370443912567985),
(3149, 1, 1, 'property', 'property', NULL, NULL, 4, 'свойство, собственность, имущество', '', 'A thread can be switched between foreground and background, and you can check whether a thread is background or foreground using the `IsBackground` {property}.', NULL, 1, '2025-08-29 23:23:11', '2026-04-24 09:29:45', 45, 43, 0.24758331873229084),
(3150, 1, 1, 'main', 'main', NULL, NULL, 99, 'главный, основной', '', '- By default, the {main} thread and threads created via `Thread` are foreground threads, while threads from the thread pool run as background threads.', NULL, 1, '2025-08-29 23:23:30', '2026-01-16 18:04:57', 100, 100, 0.17636827489022935),
(3151, 1, 1, 'via', 'via', NULL, NULL, 5, 'через, посредством', '', '- By default, the main thread and threads created {via} `Thread` are foreground threads, while threads from the thread pool run as background threads.', NULL, 1, '2025-08-29 23:23:40', '2026-04-22 18:32:16', 96, 94, 0.3267834506247039),
(3152, 1, 1, 'pool', 'pool', NULL, NULL, 5, 'бассейн, объединение; объединять', '', '- By default, the main thread and threads created via `Thread` are foreground threads, while threads from the thread {pool} run as background threads.', NULL, 1, '2025-08-29 23:24:26', '2026-02-14 09:43:55', 2, 1, 0.8911673276602917),
(3153, 1, 1, 'isolates', 'isolates', NULL, NULL, 5, 'изолировать, отделять, разграничивать', '', 'This {isolates} processes from each other, ensuring that one process cannot affect the data of another.', NULL, 1, '2025-08-29 23:24:41', '2026-02-27 10:50:03', 20, 19, 0.47548631716099227),
(3154, 1, 1, 'located', 'located', NULL, NULL, 99, 'расположенный, размещенный', '', 'The `new` operator returns the memory address where the object itself is {located}.', NULL, 1, '2025-08-29 23:25:35', '2026-01-17 12:47:44', 100, 100, 0.5499069761018334),
(3155, 1, 1, 'determined', 'determined', NULL, NULL, 5, 'определённый, установленный, заданный', '', 'Its size is {determined} by the length of the value type and two additional members — an object pointer and a sync block index.', NULL, 1, '2025-08-29 23:28:41', '2026-02-22 10:36:44', 13, 12, 0.703929633557731),
(3156, 1, 1, 'pointer', 'pointer', NULL, NULL, 99, 'указка, указатель, ссылка, маркер; указывать, направлять; подсказка, совет; порода охотничьей собаки', '', 'Its size is determined by the length of the value type and two additional members — an object {pointer} and a sync block index. The teacher used a {pointer} on the screen, gave me a helpful {pointer} about my CV, and later her {pointer} ran after birds in the park.', '', 1, '2025-08-29 23:28:52', '2026-04-24 09:37:15', 100, 100, 0.7687082521325985),
(3157, 1, 1, 'sync block', 'sync block', NULL, NULL, 99, 'блок синхронизации', '', '', NULL, 2, '2025-08-29 23:29:20', '2026-01-18 19:06:33', 100, 100, 0.45201915824042554),
(3158, 1, 1, 'index', 'index', NULL, NULL, 99, 'индекс, номер; индексировать', '', 'Its size is determined by the length of the value type and two additional members — an object pointer and a sync block {index}.', NULL, 1, '2025-08-29 23:29:45', '2026-01-19 14:44:48', 100, 100, 0.3911759605549052),
(3159, 1, 1, 'meaning', 'meaning', NULL, NULL, 5, 'значение, смысл, обозначение; означать, значить', '', 'This address is a reference to the object, {meaning} the value type is turned into a reference type.', NULL, 1, '2025-08-29 23:30:01', '2026-01-19 14:40:48', -34, -36, 0.09318924703932298),
(3160, 1, 1, 'Unboxing', 'unboxing', NULL, NULL, 5, 'распаковка', '', '{Unboxing} is the copying of fields from a boxed object located on the heap into an unboxed object located on the thread stack.', NULL, 1, '2025-08-29 23:30:10', '2026-02-14 10:09:22', 2, 1, 0.35415736525706704),
(3161, 1, 1, 'copying', 'copying', NULL, NULL, 5, 'копирование, дублирование, перенос; копировать, дублировать, переносить', '', 'Unboxing is the {copying} of fields from a boxed object located on the heap into an unboxed object located on the thread stack.', NULL, 1, '2025-08-29 23:30:22', '2026-02-22 10:43:14', 13, 12, 0.49121911590101114),
(3162, 1, 1, 'obtained', 'obtained', NULL, NULL, 5, 'полученный, извлечённый; получать, извлекать', '', 'First, the address of the boxed object\'s fields is {obtained}, then those fields are copied from the heap into the instance of the value type on the stack.', NULL, 1, '2025-08-29 23:30:39', '2026-04-22 18:10:59', 96, 94, 0.3936235144674997),
(3163, 1, 1, 'points', 'points', NULL, NULL, 5, 'указывает, направляет, точки, моменты; указывать, направлять', '', 'If the reference {points} to an object that is not a boxed instance of the required value type, an `InvalidCastException` is thrown.', NULL, 1, '2025-08-29 23:31:03', '2026-02-14 09:42:17', 2, 1, 0.49446025536811006),
(3164, 1, 1, 'InvalidCastException', 'invalidcastexception', NULL, NULL, 99, 'InvalidCastException, исключение неверного приведения', '', 'If the reference points to an object that is not a boxed instance of the required value type, an `{InvalidCastException}` is thrown.', NULL, 1, '2025-08-29 23:31:10', '2026-01-27 13:05:09', 100, 100, 0.5620165584255165),
(3165, 1, 1, 'resource-intensive', 'resource-intensive', NULL, NULL, 5, 'ресурсоёмкий, требовательный к ресурсам', '', '', NULL, 2, '2025-08-29 23:31:55', '2026-02-28 09:29:19', 22, 20, 0.29143076417169606),
(3166, 1, 1, 'constant', 'constant', NULL, NULL, 5, 'константа, постоянный', '', 'A {constant} is an implicitly static member of a type whose value never changes, is determined at compile time, and is stored in the module\'s metadata.', NULL, 1, '2025-08-29 23:32:11', '2026-02-28 09:28:30', 22, 20, 0.9737730854877952),
(3167, 1, 1, 'member', 'member', NULL, NULL, 99, 'член, участник, представитель', '', 'A constant is an implicitly static {member} of a type whose value never changes, is determined at compile time, and is stored in the module\'s metadata.', NULL, 1, '2025-08-29 23:32:24', '2026-04-24 09:30:05', 100, 100, 0.46134286416819587),
(3168, 1, 1, 'implicitly', 'implicitly', NULL, NULL, 5, 'неявно', '', 'A constant is an {implicitly} static member of a type whose value never changes, is determined at compile time, and is stored in the module\'s metadata.', NULL, 1, '2025-08-29 23:32:42', '2026-02-24 13:06:09', 16, 15, 0.9945731656575325),
(3169, 1, 1, 'changes', 'changes', NULL, NULL, 99, 'изменения, перемены; изменять, менять', '', 'A constant is an implicitly static member of a type whose value never {changes}, is determined at compile time, and is stored in the module\'s metadata.', NULL, 1, '2025-08-29 23:32:55', '2026-04-24 09:30:01', 100, 100, 0.4348105615329096),
(3170, 1, 1, 'compile', 'compile', NULL, NULL, 5, 'компиляция, сборка; компилировать, собирать', '', 'A constant is an implicitly static member of a type whose value never changes, is determined at {compile} time, and is stored in the module\'s metadata.', NULL, 1, '2025-08-29 23:33:11', '2026-02-14 10:10:46', 2, 1, 0.051546602557922344),
(3171, 1, 1, 'module\'s', 'module\'s', NULL, NULL, 99, 'модуль, блок', '', 'A constant is an implicitly static member of a type whose value never changes, is determined at compile time, and is stored in the {module\'s} metadata.', NULL, 1, '2025-08-29 23:33:19', '2026-02-15 12:49:45', 100, 100, 0.7546989915470583),
(3172, 1, 1, 'improve', 'improve', NULL, NULL, 99, 'улучшать, совершенствовать', '', 'Constant is used to {improve} code readability and maintainability.', NULL, 1, '2025-08-29 23:33:34', '2026-01-19 14:41:19', 100, 100, 0.5185844111429382),
(3173, 1, 1, 'readability', 'readability', NULL, NULL, 5, 'читаемость, удобочитаемость', '', 'Constant is used to improve code {readability} and maintainability.', NULL, 1, '2025-08-29 23:33:51', '2026-02-22 10:36:04', 13, 12, 0.274013546550659),
(3174, 1, 1, 'maintainability', 'maintainability', NULL, NULL, 5, 'сопровождаемость, поддерживаемость', '', 'Constant is used to improve code readability and {maintainability}.', NULL, 1, '2025-08-29 23:34:00', '2026-02-26 12:55:40', 19, 17, 0.21542795581317317),
