(3176, 1, 1, 'otherwise', 'otherwise', NULL, NULL, 5, 'иначе, в противном случае', '', '{otherwise}, it is better to use fields.', NULL, 1, '2025-08-29 23:34:18', '2026-02-23 10:26:40', 15, 13, 0.6292120140317939),
(3177, 1, 1, 'stores', 'stores', NULL, NULL, 99, 'хранение, склад, запас; хранить, содержать, сохранять', '', 'A field is a member of a type that {stores} either an instance of a value type or a reference to a reference type.', NULL, 1, '2025-08-30 15:07:18', '2026-04-24 09:29:26', 100, 100, 0.9341428465527881),
(3178, 1, 1, 'mutable', 'mutable', NULL, NULL, 5, 'изменяемый, мутабельный', '', 'Fields can be read-write ({mutable}) or read-only (immutable).', NULL, 1, '2025-08-30 15:07:40', '2026-02-26 13:03:19', 19, 17, 0.3807625904500136),
