(3180, 1, 1, 'Immutability', 'immutability', NULL, NULL, 5, 'неизменяемость, иммутабельность', '', '{Immutability} of a field of a reference type means the reference itself cannot change, not the object it points to;', NULL, 1, '2025-08-30 15:07:59', '2026-02-14 10:07:39', 2, 1, 0.01617694088833122),
(3181, 1, 1, 'modify', 'modify', NULL, NULL, 5, 'изменять, модифицировать', '', 'for example, you can still {modify} elements in an array.', NULL, 1, '2025-08-30 15:08:10', '2026-03-04 10:12:54', 27, 26, 0.9385969638252603),
