(3337, 1, 1, 'response', 'response', NULL, NULL, 5, 'ответ, реакция', '', 'Events are a mechanism where some objects raise events, and subscribers or event handlers subscribe to them and perform appropriate actions in {response} to the events.', NULL, 1, '2025-08-30 18:12:26', '2026-02-23 10:30:46', 15, 13, 0.0015528583913602479),
(3338, 1, 1, 'event\'s', 'event\'s', NULL, NULL, 99, 'события (притяж.)', '', 'To subscribe to an event, you define a method that will handle the event and then add this method to the {event\'s} handler list.', NULL, 1, '2025-08-30 18:12:26', '2026-02-05 10:25:48', 100, 100, 0.16508531958338368),
(3339, 1, 1, 'handler', 'handler', NULL, NULL, 5, 'обработчик; дрессировщик, проводник', '', 'To subscribe to an event, you define a method that will handle the event and then add this method to the event\'s {handler} list.', NULL, 1, '2025-08-30 18:12:26', '2026-02-22 10:38:59', 13, 12, 0.13212635752943006),
(3340, 1, 1, 'pass', 'pass', NULL, NULL, 5, 'передача, проход; передавать, пропускать', '', 'To {pass} additional information to subscribers when the event occurs, encapsulate the data in a new class;', NULL, 1, '2025-08-30 18:12:26', '2026-02-23 10:40:57', 15, 13, 0.6559732432067145),
(3341, 1, 1, 'convention', 'convention', NULL, NULL, 5, 'соглашение, условность', '', 'by {convention}, this type should inherit from EventArgs, and its name should end with EventArgs.', NULL, 1, '2025-08-30 18:12:26', '2026-02-26 13:02:12', 19, 17, 0.8834871741789274),
(3342, 1, 1, 'inherit', 'inherit', NULL, NULL, 99, 'наследование; наследовать', '', 'by convention, this type should {inherit} from EventArgs, and its name should end with EventArgs.', NULL, 1, '2025-08-30 18:12:26', '2026-04-24 08:44:43', 100, 100, 0.7779563309419494),
(3343, 1, 1, 'unlike', 'unlike', NULL, NULL, 5, 'непохожий, иной, в отличие от', '', 'A delegate, {unlike} an event, delegates its work to external code by invoking methods of other objects.', NULL, 1, '2025-08-30 18:12:26', '2026-02-24 13:33:49', 16, 15, 0.4495161720081383),
(3344, 1, 1, 'delegates', 'delegates', NULL, NULL, 4, 'делегаты, представители; делегировать', '', 'A delegate, unlike an event, {delegates} its work to external code by invoking methods of other objects.', NULL, 1, '2025-08-30 18:12:26', '2026-04-24 09:41:33', 45, 43, 0.5971193682375544),
(3345, 1, 1, 'external', 'external', NULL, NULL, 99, 'внешний, наружный', '', 'A delegate, unlike an event, delegates its work to {external} code by invoking methods of other objects.', NULL, 1, '2025-08-30 18:12:26', '2026-01-17 12:50:09', 100, 100, 0.30635310831140083),
(3346, 1, 1, 'invoking', 'invoking', NULL, NULL, 99, 'вызов; вызывать', '', 'A delegate, unlike an event, delegates its work to external code by {invoking} methods of other objects.', NULL, 1, '2025-08-30 18:12:26', '2026-04-22 19:54:58', 100, 100, 0.40751401000424664),
(3347, 1, 1, 'callback', 'callback', NULL, NULL, 99, 'обратный вызов; выполнять обратный вызов', '', 'A delegate is a type-safe {callback} that can invoke methods of other objects and can also invoke multiple methods in sequence.', NULL, 1, '2025-08-30 18:12:26', '2026-04-23 09:55:17', 100, 100, 0.0845047171083323),
(3348, 1, 1, 'sequence', 'sequence', NULL, NULL, 5, 'последовательность, ряд', '', 'A delegate is a type-safe callback that can invoke methods of other objects and can also invoke multiple methods in {sequence}.', NULL, 1, '2025-08-30 18:12:26', '2026-02-14 10:10:32', 2, 1, 0.6370483558970023),
(3349, 1, 1, 'internal', 'internal', NULL, NULL, 99, 'внутренний', '', '{internal} delegate void Feedback(Int32 value);', NULL, 1, '2025-08-30 18:12:26', '2026-01-18 17:09:43', 100, 100, 0.3919573904871544),
(3350, 1, 1, 'Feedback', 'feedback', NULL, NULL, 99, 'отзыв, обратная связь', '', '{Feedback} {feedback} = new {Feedback}(MethodName);', NULL, 1, '2025-08-30 18:12:26', '2026-01-17 17:58:24', 100, 100, 0.6971166298697857),
(3351, 1, 1, 'MethodName', 'methodname', NULL, NULL, 99, 'MethodName (имя метода)', '', 'Feedback feedback = new Feedback({MethodName});', NULL, 1, '2025-08-30 18:12:26', '2026-01-18 18:48:12', 100, 100, 0.9010785379457088),
(3352, 1, 1, 'delegate\'s', 'delegate\'s', NULL, NULL, 99, 'делегата (притяж.)', '', 'The methods assigned to a delegate must have a signature compatible with the {delegate\'s} signature—this means both must accept the same parameters and return the same type.', NULL, 1, '2025-08-30 18:12:26', '2026-01-18 19:05:16', 100, 100, 0.1850900176773686),
(3353, 1, 1, 'accept', 'accept', NULL, NULL, 5, 'принятие, согласие; принимать, соглашаться', '', 'The methods assigned to a delegate must have a signature compatible with the delegate\'s signature—this means both must {accept} the same parameters and return the same type.', NULL, 1, '2025-08-30 18:12:26', '2026-02-26 13:03:41', 19, 17, 0.39388370550599294),
(3354, 1, 1, 'BeginInvoke', 'begininvoke', NULL, NULL, 99, 'BeginInvoke (метод)', '', 'Essentially, a delegate is a class that contains four methods: a constructor, as well as `Invoke`, `{BeginInvoke}`, and `EndInvoke`.', NULL, 1, '2025-08-30 18:12:26', '2026-01-18 10:05:31', 100, 100, 0.3961430726536951),
(3355, 1, 1, 'EndInvoke', 'endinvoke', NULL, NULL, 99, 'EndInvoke (метод)', '', 'Essentially, a delegate is a class that contains four methods: a constructor, as well as `Invoke`, `BeginInvoke`, and `{EndInvoke}`.', NULL, 1, '2025-08-30 18:12:26', '2025-09-03 18:09:31', 100, 100, 0.9567471891238793),
(3356, 1, 1, 'global', 'global', NULL, NULL, 99, 'глобальный, мировой', '', 'A delegate can be defined inside a class or in the {global} scope.', NULL, 1, '2025-08-30 18:12:26', '2026-01-17 12:59:54', 100, 100, 0.04368020784452577),
(3357, 1, 1, 'Multicast', 'multicast', NULL, NULL, 5, 'мультикаст, многадресный', '', '{Multicast} delegates (chaining) are collections of delegates that allow a delegate to invoke multiple methods.', NULL, 1, '2025-08-30 18:12:26', '2026-02-14 09:41:12', 2, 1, 0.05827349057260295),
(3358, 1, 1, 'chaining', 'chaining', NULL, NULL, 5, 'цепочка, связывание; цеплять, связывать', '', 'Multicast delegates ({chaining}) are collections of delegates that allow a delegate to invoke multiple methods.', NULL, 1, '2025-08-30 18:12:26', '2026-02-26 12:55:45', 19, 17, 0.10971636707868089),
(3359, 1, 1, 'collections', 'collections', NULL, NULL, 99, 'коллекции, собрания; собирать, коллекционировать', '', 'Multicast delegates (chaining) are {collections} of delegates that allow a delegate to invoke multiple methods.', NULL, 1, '2025-08-30 18:12:26', '2026-04-24 08:48:36', 100, 100, 0.9970637680935336),
(3360, 1, 1, 'convenient', 'convenient', NULL, NULL, 99, 'удобный, подходящий', '', 'For {convenient} addition and removal, the operators += and -= are overloaded, which call Delegate.Combine and Delegate.Remove respectively.', NULL, 1, '2025-08-30 18:12:26', '2026-04-24 08:48:12', 100, 100, 0.0634743199343554);
INSERT INTO `words` (`WoID`, `WoUsID`, `WoLgID`, `WoText`, `WoTextLC`, `WoLemma`, `WoLemmaLC`, `WoStatus`, `WoTranslation`, `WoRomanization`, `WoSentence`, `WoNotes`, `WoWordCount`, `WoCreated`, `WoStatusChanged`, `WoTodayScore`, `WoTomorrowScore`, `WoRandom`) VALUES
(3361, 1, 1, 'removal', 'removal', NULL, NULL, 5, 'удаление, устранение; удалять, устранять', '', 'For convenient addition and {removal}, the operators += and -= are overloaded, which call Delegate.Combine and Delegate.Remove respectively.', NULL, 1, '2025-08-30 18:12:26', '2026-02-24 13:37:52', 16, 15, 0.3737613944092406),
(3362, 1, 1, 'Delegate.', 'delegate.', NULL, NULL, 99, 'Delegate. (тип)', '', 'For convenient addition and removal, the operators += and -= are overloaded, which call Delegate.Combine and Delegate.Remove respectively.', NULL, 1, '2025-08-30 18:12:26', '2026-01-18 19:05:18', 100, 100, 0.6550388286402811),
(3363, 1, 1, 'Combine', 'combine', NULL, NULL, 5, 'комбинирование, объединение; комбинировать, объединять', '', 'For convenient addition and removal, the operators += and -= are overloaded, which call Delegate.{Combine} and Delegate.Remove respectively.', NULL, 1, '2025-08-30 18:12:26', '2026-02-14 09:46:41', 2, 1, 0.5396579015438053),
(3364, 1, 1, 'Remove', 'remove', NULL, NULL, 5, 'удаление, исключение; удалять, исключать', '', 'For convenient addition and removal, the operators += and -= are overloaded, which call Delegate.Combine and Delegate.{Remove} respectively.', NULL, 1, '2025-08-30 18:12:26', '2026-02-23 10:41:44', 15, 13, 0.5770053552249497),
(3365, 1, 1, 'respectively', 'respectively', NULL, NULL, 5, 'соответственно', '', 'For convenient addition and removal, the operators += and -= are overloaded, which call Delegate.Combine and Delegate.Remove {respectively}.', NULL, 1, '2025-08-30 18:12:26', '2026-02-14 09:41:30', 2, 1, 0.2660531022269773),
(3366, 1, 1, 'invocation', 'invocation', NULL, NULL, 5, 'вызов; вызывать, инвокировать', '', 'If the delegate has a return value, the value returned is that of the last method in the {invocation} list.', NULL, 1, '2025-08-30 18:12:26', '2026-02-26 12:53:03', 19, 17, 0.5992494761936827),
(3367, 1, 1, 'Alternatively', 'alternatively', NULL, NULL, 5, 'альтернативно, иначе', '', '{Alternatively}, you can use the instance method GetInvocationList of MulticastDelegate to call each delegate explicitly.', NULL, 1, '2025-08-30 18:12:26', '2026-04-22 18:14:57', 96, 94, 0.19808810502112667),
(3368, 1, 1, 'GetInvocationList', 'getinvocationlist', NULL, NULL, 99, 'GetInvocationList (метод)', '', 'Alternatively, you can use the instance method {GetInvocationList} of MulticastDelegate to call each delegate explicitly.', NULL, 1, '2025-08-30 18:12:26', '2025-09-03 17:10:28', 100, 100, 0.42190955152912957),
(3369, 1, 1, 'MulticastDelegate', 'multicastdelegate', NULL, NULL, 99, 'MulticastDelegate (тип)', '', 'Alternatively, you can use the instance method GetInvocationList of {MulticastDelegate} to call each delegate explicitly.', NULL, 1, '2025-08-30 18:12:26', '2026-01-18 19:06:20', 100, 100, 0.9290476906383854),
(3370, 1, 1, 'lambda', 'lambda', NULL, NULL, 4, 'лямбда-выражение, λ', '', 'You can also use a {lambda} expression to provide a delegate implementation directly in the code, without explicitly defining a delegate type.', NULL, 1, '2025-08-30 18:12:26', '2026-04-22 13:57:59', 41, 39, 0.19269212725823012),
(3371, 1, 1, 'covariance', 'covariance', NULL, NULL, 99, 'ковариантность', '', 'Delegates support {covariance} and contravariance.', NULL, 1, '2025-08-30 18:12:26', '2026-01-19 14:41:27', 100, 100, 0.6100563990045864),
(3372, 1, 1, 'contravariance', 'contravariance', NULL, NULL, 5, 'контравариантность', '', 'Delegates support covariance and {contravariance}.', NULL, 1, '2025-08-30 18:12:26', '2026-04-23 09:53:43', 97, 96, 0.3691963519614156),
(3373, 1, 1, 'built', 'built', NULL, NULL, 99, 'построенный, созданный; строить, создавать', '', 'There are also {built}-in delegates:', NULL, 1, '2025-08-30 18:12:26', '2026-04-24 09:32:29', 100, 100, 0.21580301338415875),
(3374, 1, 1, 'Func', 'func', NULL, NULL, 99, 'Func, делегат Func', '', 'Action, {Func}, and Predicate.', NULL, 1, '2025-08-30 18:12:26', '2026-01-18 17:08:32', 100, 100, 0.23003877813931442),
(3375, 1, 1, 'Predicate', 'predicate', NULL, NULL, 99, 'Predicate, делегат Predicate, предикат', '', 'Action, Func, and {Predicate}.', NULL, 1, '2025-08-30 18:12:26', '2026-04-23 09:54:31', 100, 100, 0.4548159823332131),
(3376, 1, 1, 'applies', 'applies', NULL, NULL, 5, 'применять; распространяться; подаёт заявку for', '', 'The same {applies} when implementing an interface method: the implementing method\'s type parameters inherit the interface method\'s constraints.', NULL, 1, '2025-08-30 18:12:26', '2026-02-15 10:14:34', 3, 2, 0.2679054087660326),
(3377, 1, 1, 'flexibility', 'flexibility', NULL, NULL, 5, 'гибкость, эластичность', '', 'When creating a generic delegate with type parameters, the compiler automatically applies the type parameters to all methods of the delegate, including parameters and return values, which provides {flexibility} and type safety.', NULL, 1, '2025-08-30 18:12:26', '2026-02-23 10:30:56', 15, 13, 0.2319380186795611),
(3378, 1, 1, 'following', 'following', NULL, NULL, 5, 'следующий; следовать', '', 'A type parameter can have the {following} constraints: primary, secondary, and/or the constructor constraint.', NULL, 1, '2025-08-30 18:12:26', '2026-02-23 10:25:26', 15, 13, 0.3559738978333528),
(3379, 1, 1, 'arguments', 'arguments', NULL, NULL, 5, 'аргументы, параметры', '', 'Calling a method that accepts a variable number of {arguments} can reduce performance.', NULL, 1, '2025-08-30 18:12:26', '2026-02-14 09:48:36', 2, 1, 0.08405546386172573),
(3380, 1, 1, 'instances', 'instances', NULL, NULL, 99, 'экземпляры', '', 'The C# compiler treats enumerated types as primitive, so you can use operators with their {instances} (`==`, `!', NULL, 1, '2025-08-30 18:12:26', '2026-01-18 09:59:26', 100, 100, 0.17465402015918308),
(3381, 1, 1, 'typed', 'typed', NULL, NULL, 99, 'набранный, типизированный; печатать, набирать', '', 'An implicitly {typed} local variable is a variable marked with the var keyword.', NULL, 1, '2025-08-30 18:12:26', '2026-04-24 09:40:45', 100, 100, 0.33205356759210447),
(3382, 1, 1, 'var', 'var', NULL, NULL, 99, 'var, переменная', '', '{var} tom = new Person(\"Tom\", 37);', NULL, 1, '2025-08-30 18:12:26', '2025-09-03 17:57:49', 100, 100, 0.029258272637853654),
(3383, 1, 1, 'side', 'side', NULL, NULL, 99, 'сторона, бок, побочный', '', 'To determine its type, the compiler looks at the type of the expression on the right {side} of the assignment operator (`=`).', NULL, 1, '2025-08-30 18:12:26', '2026-01-19 14:47:34', 100, 100, 0.11410467430400166),
(3384, 1, 1, 'assignment', 'assignment', NULL, NULL, 99, 'присваивание, назначение; присваивать, назначать', '', 'To determine its type, the compiler looks at the type of the expression on the right side of the {assignment} operator (`=`).', NULL, 1, '2025-08-30 18:12:26', '2026-01-18 17:04:18', 100, 100, 0.3645076326695342),
(3385, 1, 1, 'passing', 'passing', NULL, NULL, 4, 'передавать, проходить', '', 'The keywords `out`, `ref`, and `in` allow {passing} parameters by reference instead of by value.', NULL, 1, '2025-08-30 18:12:26', '2026-04-24 08:51:43', 45, 43, 0.3523556565422152),
(3386, 1, 1, 'receives', 'receives', NULL, NULL, 99, 'получать, принимать', '', 'When passing a reference type to a method, the method {receives} a reference to that object.', NULL, 1, '2025-08-30 18:12:26', '2026-04-24 09:37:05', 100, 100, 0.27112394689686964),
(3387, 1, 1, 'affecting', 'affecting', NULL, NULL, 5, 'влияние, воздействие; влиять, воздействовать', '', 'This means the method can modify the passed object, {affecting} the state in the calling code.', NULL, 1, '2025-08-30 18:12:26', '2026-04-22 18:34:40', 96, 94, 0.5096119218595437),
(3388, 1, 1, 'original', 'original', NULL, NULL, 99, 'оригинальный, исходный', '', 'Changes to the copy do not affect the {original} object.', NULL, 1, '2025-08-30 18:12:26', '2026-01-18 10:11:02', 100, 100, 0.17189312369738996),
(3389, 1, 1, 'avoids', 'avoids', NULL, NULL, 99, 'избегать, уклоняться', '', 'This improves performance with value types, as it {avoids} copying their fields and allows the method to work with a single instance of the value type.', NULL, 1, '2025-08-30 18:12:26', '2026-01-18 10:04:49', 100, 100, 0.1666902593958101),
(3390, 1, 1, 'caller', 'caller', NULL, NULL, 5, 'вызывающий, вызывающая сторона', '', 'Works the same as `in`, but requires the {caller} to specify `ref` or `in` in the method call, which adds clarity.', NULL, 1, '2025-08-30 18:12:26', '2026-04-22 18:57:25', 96, 94, 0.49099267040471795),
(3391, 1, 1, 'parameter\'s', 'parameter\'s', NULL, NULL, 99, 'параметра', '', 'The caller must initialize the variable before calling the method, and the called method can both read and write the {parameter\'s} value.', NULL, 1, '2025-08-30 18:12:26', '2026-01-31 11:33:28', 100, 100, 0.3844951459993563),
(3392, 1, 1, 'optional', 'optional', NULL, NULL, 4, 'необязательный, опциональный', '', 'The `in` keyword is {optional} when calling the method.', NULL, 1, '2025-08-30 18:12:26', '2026-04-22 19:54:07', 41, 39, 0.9261276171786037),
(3393, 1, 1, 'clarity', 'clarity', NULL, NULL, 5, 'ясность, понятность', '', 'Works the same as `in`, but requires the caller to specify `ref` or `in` in the method call, which adds {clarity}.', NULL, 1, '2025-08-30 18:12:26', '2026-04-22 18:19:35', 96, 94, 0.15766010541250938),
(3394, 1, 1, 'allocates', 'allocates', NULL, NULL, 5, 'выделять, распределять', '', 'For reference types passed by reference: the calling code {allocates} memory for the pointer to the object being passed, and the called code manages this pointer.', NULL, 1, '2025-08-30 18:12:26', '2026-02-14 10:05:52', 2, 1, 0.009917706260380993),
(3395, 1, 1, 'manages', 'manages', NULL, NULL, 5, 'управлять, распоряжаться', '', 'The Garbage Collector (GC) is a mechanism that {manages} memory allocation and deallocation for an application.', NULL, 1, '2025-08-30 18:12:26', '2026-02-23 10:24:49', 15, 13, 0.5766082457980218),
(3396, 1, 1, 'contrast', 'contrast', NULL, NULL, 4, 'различие, отличие; сравнить, противопоставить', '', 'In {contrast}, when passing a reference type by value, you can change the values of the object, but assigning a new reference will not affect the original object.', NULL, 1, '2025-08-30 18:12:26', '2026-04-22 17:38:05', 41, 39, 0.853288140942611),
