(3506, 1, 1, 'y', 'y', NULL, NULL, 99, 'y, переменная «y»', '', '{y} = null;', NULL, 1, '2025-08-30 19:02:34', '2025-09-01 22:17:57', 100, 100, 0.14914164612921108),
(3507, 1, 1, 'HasValue', 'hasvalue', NULL, NULL, 99, 'HasValue, «имеет значение»', '', '- {HasValue} - returns `true` if the variable contains a value, and `false` if it is `null`.', NULL, 1, '2025-08-30 19:02:34', '2026-01-19 12:17:04', 100, 100, 0.5332872900490531),
(3508, 1, 1, 'multiplication', 'multiplication', NULL, NULL, 99, 'умножение', '', 'The result of addition, {multiplication}, comparison, etc., will always be `null` if at least one of the operands is `null` or `false`.', NULL, 1, '2025-08-30 19:02:34', '2026-04-24 09:32:37', 100, 100, 0.35366512588566645),
(3509, 1, 1, 'operands', 'operands', NULL, NULL, 3, 'операнды, аргументы', '', 'The result of addition, multiplication, comparison, etc., will always be `null` if at least one of the {operands} is `null` or `false`.', NULL, 1, '2025-08-30 19:02:34', '2026-04-22 17:46:45', 13, 11, 0.4918989133945656),
(3510, 1, 1, 'x', 'x', NULL, NULL, 99, 'x, переменная «x»', '', '{x} = 5;', NULL, 1, '2025-08-30 19:02:34', '2025-09-01 17:05:11', 100, 100, 0.21674883013288382),
(3511, 1, 1, 'z', 'z', NULL, NULL, 99, 'z, переменная «z»', '', 'int {z} = x + 7; // Not allowed', NULL, 1, '2025-08-30 19:02:34', '2025-09-01 16:45:36', 100, 100, 0.7400288747065038),
(3512, 1, 1, 'w', 'w', NULL, NULL, 99, 'w, переменная «w»', '', '{w} = x + 7; // Allowed', NULL, 1, '2025-08-30 19:02:34', '2025-09-01 22:10:36', 100, 100, 0.5503618899270537),
