INSERT INTO `words` (`WoID`, `WoUsID`, `WoLgID`, `WoText`, `WoTextLC`, `WoLemma`, `WoLemmaLC`, `WoStatus`, `WoTranslation`, `WoRomanization`, `WoSentence`, `WoNotes`, `WoWordCount`, `WoCreated`, `WoStatusChanged`, `WoTodayScore`, `WoTomorrowScore`, `WoRandom`) VALUES
(3744, 1, 1, 'constructs', 'constructs', NULL, NULL, 99, 'конструкции; конструировать, строить', '', 'When working with these {constructs}, the code you write is placed inside a try block, and the cleanup code is placed in the finally block.', NULL, 1, '2025-08-31 19:44:44', '2026-04-23 15:41:24', 100, 100, 0.1204672810812176),
(3745, 1, 1, 'releases', 'releases', NULL, NULL, 99, 'освобождение, выпуск; освобождать, выпускать', '', '- lock: the finally block {releases} the lock (Monitor.Exit).', NULL, 1, '2025-08-31 19:44:44', '2026-01-19 14:44:16', 100, 100, 0.20077324677330743),
(3746, 1, 1, 'Monitor.', 'monitor.', NULL, NULL, 99, 'Monitor, класс Monitor', '', '- lock: the finally block releases the lock ({Monitor.}Exit).', NULL, 1, '2025-08-31 19:44:44', '2026-04-24 08:48:16', 100, 100, 0.2036196721751426),
(3747, 1, 1, 'Exit', 'exit', NULL, NULL, 3, 'Exit, метод Exit; выходить, освобождать (монитор)', '', '- lock: the finally block releases the lock (Monitor.{Exit}).', NULL, 1, '2025-08-31 19:44:44', '2026-04-22 18:10:30', 13, 11, 0.1295336672379949),
(3748, 1, 1, 'Dispose', 'dispose', NULL, NULL, 5, 'уничтожение; освобождать, уничтожать', '', '- using: the finally block calls {Dispose} on the object.', NULL, 1, '2025-08-31 19:44:44', '2026-02-23 10:40:48', 15, 13, 0.7556389502767836),
(3749, 1, 1, 'IEnumerator', 'ienumerator', NULL, NULL, 99, 'IEnumerator (интерфейс)', '', '- foreach: the finally block calls Dispose on the {IEnumerator} (if it implements IDisposable).', NULL, 1, '2025-08-31 19:44:44', '2025-09-07 17:13:13', 100, 100, 0.5836497299220876),
(3750, 1, 1, 'IDisposable', 'idisposable', NULL, NULL, 99, 'IDisposable (интерфейс)', '', '- foreach: the finally block calls Dispose on the IEnumerator (if it implements {IDisposable}).', NULL, 1, '2025-08-31 19:44:44', '2025-09-02 15:03:50', 100, 100, 0.2544193596154632),
(3751, 1, 1, 'base.', 'base.', NULL, NULL, 99, 'base, базовый', '', '- destructor (~Type): the finally block calls {base.}Finalize().', NULL, 1, '2025-08-31 19:44:44', '2025-09-02 15:04:43', 100, 100, 0.5908661527474096),
(3752, 1, 1, 'finalizer', 'finalizer', NULL, NULL, 5, 'финализатор', '', 'Finalize ({finalizer}) is a destructor (~TypeName) used to explicitly release unmanaged resources when the garbage collector (GC) is called.', NULL, 1, '2025-08-31 19:44:44', '2026-02-15 10:16:43', 3, 2, 0.38959378040357845),
(3753, 1, 1, 'TypeName', 'typename', NULL, NULL, 99, 'имя типа, TypeName', '', 'Finalize (finalizer) is a destructor (~{TypeName}) used to explicitly release unmanaged resources when the garbage collector (GC) is called.', NULL, 1, '2025-08-31 19:44:44', '2025-09-02 15:04:03', 100, 100, 0.21136404221073168),
(3754, 1, 1, 'release', 'release', NULL, NULL, 99, 'выпуск, освобождение; выпускать, освобождать', '', 'Finalize (finalizer) is a destructor (~TypeName) used to explicitly {release} unmanaged resources when the garbage collector (GC) is called.', NULL, 1, '2025-08-31 19:44:44', '2026-04-24 08:51:57', 100, 100, 0.21090384871783094),
(3755, 1, 1, 'unmanaged', 'unmanaged', NULL, NULL, 99, 'неуправляемый', '', 'Finalize (finalizer) is a destructor (~TypeName) used to explicitly release {unmanaged} resources when the garbage collector (GC) is called.', NULL, 1, '2025-08-31 19:44:44', '2026-01-18 18:54:42', 100, 100, 0.6482207315491706),
(3756, 1, 1, 'database', 'database', NULL, NULL, 99, 'база данных', '', 'Unmanaged resources are objects that are not managed by garbage collector and not part of .NET, such as {database} connections, network connections, file or socket handles.', NULL, 1, '2025-08-31 19:44:44', '2026-01-18 17:06:42', 100, 100, 0.7001830364579177),
(3757, 1, 1, 'connections', 'connections', NULL, NULL, 99, 'соединения, подключения; соединять', '', 'Unmanaged resources are objects that are not managed by garbage collector and not part of .NET, such as database {connections}, network {connections}, file or socket handles.', NULL, 1, '2025-08-31 19:44:44', '2026-04-24 09:35:33', 100, 100, 0.8590228630779524),
(3758, 1, 1, 'network', 'network', NULL, NULL, 99, 'сеть, сетевой', '', 'Unmanaged resources are objects that are not managed by garbage collector and not part of .NET, such as database connections, {network} connections, file or socket handles.', NULL, 1, '2025-08-31 19:44:44', '2026-01-19 14:43:59', 100, 100, 0.6751484802692649),
(3759, 1, 1, 'socket', 'socket', NULL, NULL, 4, 'сокет, разъём, гнездо, розетка, патрон', '', 'The electrician plugged the lamp into the {socket}, screwed the bulb into its {socket}, and winced so hard his eyes nearly popped out of their {socket}s when he saw the bill for the new {socket}s and network {socket}s in the office.', NULL, 1, '2025-08-31 19:44:44', '2026-04-22 13:55:44', 41, 39, 0.6810520819211864),
(3760, 1, 1, 'handles', 'handles', NULL, NULL, 5, 'обрабатывать, управлять', '', 'Unmanaged resources are objects that are not managed by garbage collector and not part of .NET, such as database connections, network connections, file or socket {handles}.', NULL, 1, '2025-08-31 19:44:44', '2026-02-26 12:59:20', 19, 17, 0.23647909912884152),
(3761, 1, 1, 'tilde', 'tilde', NULL, NULL, 5, 'тильда (~)', '', 'The syntax for declaring a finalizer is similar to that of a constructor, but with a {tilde} (`~`).', NULL, 1, '2025-08-31 19:44:44', '2026-02-15 10:20:48', 3, 2, 0.13923928061429344),
(3762, 1, 1, 'drawback', 'drawback', NULL, NULL, 5, 'недостаток, минус', '', 'A {drawback} of using finalizers is that you do not know exactly when the GC will remove the object from memory, nor the order in which objects will be finalized.', NULL, 1, '2025-08-31 19:44:44', '2026-02-22 10:32:25', 13, 12, 0.9867591364185877),
(3763, 1, 1, 'finalizers', 'finalizers', NULL, NULL, 99, 'финализаторы', '', 'A drawback of using {finalizers} is that you do not know exactly when the GC will remove the object from memory, nor the order in which objects will be finalized.', NULL, 1, '2025-08-31 19:44:44', '2026-01-19 12:50:45', 100, 100, 0.9549467553896334),
(3764, 1, 1, 'finalized', 'finalized', NULL, NULL, 3, 'завершил, доработал, утвердил, окончательно согласовал', '', 'A drawback of using finalizers is that you do not know exactly when the GC will remove the object from memory, nor the order in which objects will be {finalized}.', NULL, 1, '2025-08-31 19:44:44', '2026-04-22 18:13:51', 13, 11, 0.516077870983703),
(3765, 1, 1, 'IDisposable.', 'idisposable.', NULL, NULL, 99, 'IDisposable. (указание на интерфейс)', '', 'Dispose (`IDisposable.Dispose`) is used to explicitly release unmanaged resources by the developer or via the `using` statement.', NULL, 1, '2025-08-31 19:44:44', '2025-09-02 18:07:50', 100, 100, 0.40874311831662724),
(3766, 1, 1, 'important', 'important', NULL, NULL, 99, 'важный, значимый', '', 'It is {important} that Dispose can be called multiple times without error.', NULL, 1, '2025-08-31 19:44:44', '2026-01-17 12:55:49', 100, 100, 0.6671199199437349),
(3767, 1, 1, 'compiled', 'compiled', NULL, NULL, 5, 'скомпилированный; компилировать', '', 'The using statement is {compiled} into try/finally, though you can also write your own try/catch/finally implementation.', NULL, 1, '2025-08-31 19:44:44', '2026-02-14 09:46:45', 2, 1, 0.6201119763963967),
